mapper.select:
SELECT sku.sku , sku.sku_name , sku.sku_type , sku.spec , sku.unit , prc.unit_price_type "unit_price_type_code" , COALESCE(cmUnitType.code_name, '매출단가') "unit_price_type" , COALESCE(prc.unit_price, 0) "unit_price" , sku.tax_yn FROM tb_sku_master sku LEFT JOIN tb_unit_price_master prc ON sku.company_code = prc.company_code AND sku.sku = prc.sku
AND prc.cust_code = #{custCode}
LEFT JOIN tb_cm_code cmUnitType ON prc.unit_price_type = cmUnitType.code
sku.use_yn = 'Y'
/* 목록조건 */
AND prc.unit_price_type IN ('BUY_UNIT', 'BUY_DISC_UNIT')
AND prc.unit_price_type IN ('SELL_UNIT', 'SELL_DISC_UNIT')
/* 단가유형 선택 */
AND unit_price_type = 'SELL_UNIT'
AND unit_price_type = 'SELL_DISC_UNIT'
/* 검색조건 */
AND sku.sku like '%' || #{sku} || '%'
AND sku.sku_name like '%'|| #{skuName} ||'%'
